 "content": "from collections import Counter, deque


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append(comp)
    return comps


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)

    # The connected multicolor template is the largest component; singleton dots
    # in a distinct color indicate positions where its center should be stamped.
    motif = max(comps, key=len)
    rs = [r for r, c in motif]
    cs = [c for r, c in motif]
    top, bottom = min(rs), max(rs)
    left, right = min(cs), max(cs)
    cr, cc = (top + bottom) // 2, (left + right) // 2
    motif_colors = {grid[r][c] for r, c in motif}

    singleton_colors = Counter(grid[comp[0][0]][comp[0][1]] for comp in comps
                               if len(comp) == 1 and grid[comp[0][0]][comp[0][1]] not in motif_colors)
    marker_color = singleton_colors.most_common(1)[0][0]
    markers = [(comp[0][0], comp[0][1]) for comp in comps
               if len(comp) == 1 and grid[comp[0][0]][comp[0][1]] == marker_color]

    patch = [[grid[r][c] for c in range(left, right + 1)] for r in range(top, bottom + 1)]
    out = [row[:] for row in grid]
    for mr, mc in markers:
        for dr in range(len(patch)):
            for dc in range(len(patch[0])):
                rr, c2 = mr + dr - (cr - top), mc + dc - (cc - left)
                if 0 <= rr < h and 0 <= c2 < w:
                    out[rr][c2] = patch[dr][dc]
    return out
